INSERT INTO content_catalog_translation
(id, entry_id, locale, status, title, summary, body_markdown, knowledge_points, image_caption, revision, published_at, updated_at) VALUES
('20000000-0000-0000-0000-000000000001', '10000000-0000-0000-0000-000000000001', 'zh-CN', 'PUBLISHED', '太阳', '太阳是太阳系的中心恒星，也是地球绝大多数能量的来源。', '太阳是一颗光谱型为 G2V 的主序星。它内部的核聚变持续把氢转化为氦，并释放出光和热。\n\n从地球观察太阳必须使用合格的太阳观测滤镜，不能用肉眼、望远镜或相机直接观看。', '["太阳约占太阳系总质量的 99.86%","太阳光到达地球约需 8 分 20 秒","直接观测太阳必须使用专用滤镜"]', NULL, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('20000000-0000-0000-0000-000000000002', '10000000-0000-0000-0000-000000000001', 'en', 'PUBLISHED', 'Sun', 'The Sun is the central star of the Solar System and Earth''s primary energy source.', 'The Sun is a G2V main-sequence star. Nuclear fusion in its core converts hydrogen into helium and releases light and heat.\n\nNever look directly at the Sun through unaided eyes, binoculars, a telescope, or a camera without a certified solar filter.', '["The Sun contains about 99.86% of the Solar System''s mass","Sunlight takes about 8 minutes 20 seconds to reach Earth","Safe solar observing requires a purpose-built solar filter"]', NULL, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('20000000-0000-0000-0000-000000000003', '10000000-0000-0000-0000-000000000002', 'zh-CN', 'PUBLISHED', '月球', '月球是地球唯一的天然卫星，也是夜空中最容易观察的天体之一。', '月球本身不发光，我们看到的是它反射的太阳光。月相来自太阳、地球和月球相对位置的变化，并不是地球影子日常遮挡月球造成的。\n\n观察月球表面的环形山和月海时，明暗交界线附近通常最有立体感。', '["月相循环约为 29.5 天","月球始终以近似同一面对着地球","明暗交界线附近适合观察地貌"]', NULL, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('20000000-0000-0000-0000-000000000004', '10000000-0000-0000-0000-000000000002', 'en', 'PUBLISHED', 'Moon', 'The Moon is Earth''s only natural satellite and one of the easiest objects to observe.', 'The Moon does not make its own visible light; it reflects sunlight. Its phases result from the changing geometry of the Sun, Earth, and Moon, rather than Earth''s shadow during an ordinary month.\n\nCraters and maria often show the strongest relief close to the terminator.', '["The lunar phase cycle lasts about 29.5 days","The Moon keeps nearly the same face toward Earth","Relief is easiest to see near the terminator"]', NULL, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('20000000-0000-0000-0000-000000000005', '10000000-0000-0000-0000-000000000003', 'zh-CN', 'PUBLISHED', '织女星', '织女星是天琴座最亮的恒星，也是夏季大三角的重要顶点。', '织女星的拜耳命名是天琴座 α，HIP 编号为 91262。它是一颗距离太阳较近的明亮 A 型主序星，在北半球夏季夜空中十分醒目。\n\n织女星与牛郎星、天津四共同组成夏季大三角，是学习辨认夏季星空的理想起点。', '["属于天琴座","是夏季大三角的顶点之一","HIP 编号为 91262"]', NULL, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('20000000-0000-0000-0000-000000000006', '10000000-0000-0000-0000-000000000003', 'en', 'PUBLISHED', 'Vega', 'Vega is the brightest star in Lyra and a prominent vertex of the Summer Triangle.', 'Vega is Alpha Lyrae and is catalogued as HIP 91262. It is a nearby bright A-type main-sequence star and is conspicuous in Northern Hemisphere summer skies.\n\nTogether with Altair and Deneb, Vega forms the Summer Triangle, a useful landmark for learning the seasonal sky.', '["Located in Lyra","One vertex of the Summer Triangle","Catalogued as HIP 91262"]', NULL, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('20000000-0000-0000-0000-000000000007', '10000000-0000-0000-0000-000000000004', 'zh-CN', 'PUBLISHED', '天琴座', '天琴座是北天较小的星座，以明亮的织女星为主要标志。', '天琴座的拉丁名为 Lyra，国际天文学联合会缩写为 Lyr。虽然面积不大，但织女星让它在夏季夜空中很容易辨认。\n\n从织女星附近寻找一个由较暗恒星构成的小平行四边形，可以帮助勾勒出天琴座的主体。', '["IAU 缩写为 Lyr","主星是织女星","适合从夏季大三角开始定位"]', NULL, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('20000000-0000-0000-0000-000000000008', '10000000-0000-0000-0000-000000000004', 'en', 'PUBLISHED', 'Lyra', 'Lyra is a small northern constellation marked by the bright star Vega.', 'Lyra is abbreviated Lyr by the International Astronomical Union. Although it covers a modest area, Vega makes it easy to identify in the summer sky.\n\nA small parallelogram of fainter stars beside Vega outlines the constellation''s main shape.', '["Its IAU abbreviation is Lyr","Vega is its brightest star","It can be located from the Summer Triangle"]', NULL, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
